// GEN_FRA_FRAMA.c  (GENERATED by analysis/harness/generator.py from the spec; edit the spec, not this file)
//
// PURPOSE:  Batch harness FRA (HARNESS_DESIGN D7, adaptive smoothers). Feeds synthetic inputs through FRAMACore (8 variants:
//           FR16, FR32, NCE [control], NCN [control], NC32 [control], NCT [control], NCS [control], NCS2 [control]) and writes the RAW outputs. It does NOT judge anything.
//           Python (analysis/harness/checker.py) measures and writes PASS/FAIL.
// PREREG:   analysis/harness/specs/FRAMA_ArticleFidelity.toml (this file)
// INPUTS:   Synthetic only, from the bar counter n: flat | level+amp*sin(2*pi*n/T), T=5,10,20,40,100 | ramp level+slope*n
//           level=11/10 amp=1/100 slope=1/10000. (b, H1 run 1) Decimal literals are float32 in this Zorro
//           build and the PI macro is 3.14159, so every constant is built at run time from integers.
//           band bars rampB, s5B, s10B, s20B, s40B, s100B: the same x with High = x + h, Low = x - h, h = 2/1000; point bars pass x as Price, High and Low.
//           copy sc40B = 10/1 * s40B - 99/10 (x, High and Low mapped together)
//           copy of40B = 1/1 * s40B + 11/10 (x, High and Low mapped together)
//           EUR/USD is used only as a bar clock; clock_close is exported for the checker's magnitude guard.
// OUTPUT:   Data/GEN_FRA_raw.csv  (3000 rows n=0..2999 + header; 305 columns; values printed with 15 decimals)
// CALLS:    108 indicator calls per bar, variant-major, unconditional, fixed order (gotchas 3.1).
// FEEDING:  every x[n], n=0..2999, reaches the indicators exactly once; INITRUN and EXITRUN feed and write nothing.
// NO LOOKBACK GUARD: LookBack = 0, warmup bars are exported too; the checker requires n = 0..2999 contiguous.
// SOURCES:  expected values and tolerances are in the spec, each with an (a)/(b)/(c) label.
// Y[] slots: variant-major; per call the outputs in the listed order (the last is the return value); see the call comments.

#include <default.c>
#include "../../indicators/ehlers/FRAMA_Superseded.c"
#include "../../indicators/ehlers/FRAMA.c"

#define FRA_RAW "Data/GEN_FRA_raw.csv"
#define FRA_MARK "Data/GEN_FRA_exit_marker.txt"
#define FRA_NBARS 3000

static int fra_n = 0;
static int fra_done = 0;
static int fra_hdr = 0;
static int fra_rows = 0;

// NCE: realistic copying error (D2 rule 4: third digit): [corrected_code] with fr_k = 461/100.
var fra_nce(vars Price, vars High, vars Low, int N, var* pDim, var* pAlpha)
{
    vars fxe_n = series(0, 2);      // per-instance CurrentBar (9d.9)
    vars fxe_F = series(0, 2);
    vars fxe_D = series(0, 2);
    vars fxe_A = series(0, 2);
    fxe_n[0] = fxe_n[1] + 1;
    fxe_F[0] = fxe_F[1];  fxe_D[0] = fxe_D[1];  fxe_A[0] = fxe_A[1];   // EasyLanguage hold (FR-5: Dimen held)
    var fxe_k  = 461; fxe_k  = fxe_k/100;
    var fxe_lo = 1;   fxe_lo = fxe_lo/100;
    var fxe_u  = 1;
    var fxe_l2 = 2;   fxe_l2 = log(fxe_l2);
    int fxe_h = N/2;
    int fxe_i;
    var fxe_HH = High[0];
    var fxe_LL = Low[0];
    for(fxe_i = 1; fxe_i < N; fxe_i++) {
        if(High[fxe_i] > fxe_HH) fxe_HH = High[fxe_i];
        if(Low[fxe_i]  < fxe_LL) fxe_LL = Low[fxe_i];
    }
    var fxe_N3 = fxe_HH - fxe_LL;  fxe_N3 = fxe_N3/N;
    fxe_HH = High[0];  fxe_LL = Low[0];
    for(fxe_i = 0; fxe_i < fxe_h; fxe_i++) {
        if(High[fxe_i] > fxe_HH) fxe_HH = High[fxe_i];
        if(Low[fxe_i]  < fxe_LL) fxe_LL = Low[fxe_i];
    }
    var fxe_N1 = fxe_HH - fxe_LL;  fxe_N1 = fxe_N1/fxe_h;
    fxe_HH = High[fxe_h];  fxe_LL = Low[fxe_h];
    for(fxe_i = fxe_h; fxe_i < N; fxe_i++) {
        if(High[fxe_i] > fxe_HH) fxe_HH = High[fxe_i];
        if(Low[fxe_i]  < fxe_LL) fxe_LL = Low[fxe_i];
    }
    var fxe_N2 = fxe_HH - fxe_LL;  fxe_N2 = fxe_N2/fxe_h;
    if(fxe_N1 > 0 && fxe_N2 > 0 && fxe_N3 > 0) {
        fxe_D[0] = log(fxe_N1 + fxe_N2) - log(fxe_N3);
        fxe_D[0] = fxe_D[0]/fxe_l2;
    }
    var fxe_e = fxe_D[0] - fxe_u;
    fxe_e = fxe_k*fxe_e;
    fxe_A[0] = exp(-fxe_e);
    if(fxe_A[0] < fxe_lo) fxe_A[0] = fxe_lo;
    if(fxe_A[0] > fxe_u)  fxe_A[0] = fxe_u;
    fxe_F[0] = fxe_A[0]*Price[0] + (fxe_u - fxe_A[0])*fxe_F[1];
    if(fxe_n[0] < N + 1) fxe_F[0] = Price[0];
    *pDim   = fxe_D[0];
    *pAlpha = fxe_A[0];
    return fxe_F[0];
}

// NCN: [corrected_code] with the window N + 2 everywhere (halves, N3 divisor, start-up), i.e. frama_article(18) called with N = 16.
var fra_ncn(vars Price, vars High, vars Low, int N, var* pDim, var* pAlpha)
{
    vars fxn_n = series(0, 2);      // per-instance CurrentBar (9d.9)
    vars fxn_F = series(0, 2);
    vars fxn_D = series(0, 2);
    vars fxn_A = series(0, 2);
    fxn_n[0] = fxn_n[1] + 1;
    fxn_F[0] = fxn_F[1];  fxn_D[0] = fxn_D[1];  fxn_A[0] = fxn_A[1];   // EasyLanguage hold (FR-5: Dimen held)
    var fxn_k  = 46;  fxn_k  = fxn_k/10;
    var fxn_lo = 1;   fxn_lo = fxn_lo/100;
    var fxn_u  = 1;
    var fxn_l2 = 2;   fxn_l2 = log(fxn_l2);
    int fxn_N = N + 2;                 // NCN: window N + 2 everywhere
    int fxn_h = fxn_N/2;
    int fxn_i;
    var fxn_HH = High[0];
    var fxn_LL = Low[0];
    for(fxn_i = 1; fxn_i < fxn_N; fxn_i++) {
        if(High[fxn_i] > fxn_HH) fxn_HH = High[fxn_i];
        if(Low[fxn_i]  < fxn_LL) fxn_LL = Low[fxn_i];
    }
    var fxn_N3 = fxn_HH - fxn_LL;  fxn_N3 = fxn_N3/fxn_N;
    fxn_HH = High[0];  fxn_LL = Low[0];
    for(fxn_i = 0; fxn_i < fxn_h; fxn_i++) {
        if(High[fxn_i] > fxn_HH) fxn_HH = High[fxn_i];
        if(Low[fxn_i]  < fxn_LL) fxn_LL = Low[fxn_i];
    }
    var fxn_N1 = fxn_HH - fxn_LL;  fxn_N1 = fxn_N1/fxn_h;
    fxn_HH = High[fxn_h];  fxn_LL = Low[fxn_h];
    for(fxn_i = fxn_h; fxn_i < fxn_N; fxn_i++) {
        if(High[fxn_i] > fxn_HH) fxn_HH = High[fxn_i];
        if(Low[fxn_i]  < fxn_LL) fxn_LL = Low[fxn_i];
    }
    var fxn_N2 = fxn_HH - fxn_LL;  fxn_N2 = fxn_N2/fxn_h;
    if(fxn_N1 > 0 && fxn_N2 > 0 && fxn_N3 > 0) {
        fxn_D[0] = log(fxn_N1 + fxn_N2) - log(fxn_N3);
        fxn_D[0] = fxn_D[0]/fxn_l2;
    }
    var fxn_e = fxn_D[0] - fxn_u;
    fxn_e = fxn_k*fxn_e;
    fxn_A[0] = exp(-fxn_e);
    if(fxn_A[0] < fxn_lo) fxn_A[0] = fxn_lo;
    if(fxn_A[0] > fxn_u)  fxn_A[0] = fxn_u;
    fxn_F[0] = fxn_A[0]*Price[0] + (fxn_u - fxn_A[0])*fxn_F[1];
    if(fxn_n[0] < fxn_N + 1) fxn_F[0] = Price[0];
    *pDim   = fxn_D[0];
    *pAlpha = fxn_A[0];
    return fxn_F[0];
}

